package cupti

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"sort"
	"strings"
	"sync"
	"sync/atomic"
	"unsafe"

	"github.com/ebitengine/purego"
	"github.com/tmc/lib/nvidia/internal/ffi"
)

var (
	loadMu    sync.Mutex
	attempted bool
	lib       uintptr
	libErr    error
	libPath   string

	// ready is the fast path for checkLib: once the library has loaded
	// successfully, calls skip loadMu entirely.
	ready atomic.Bool

	// explicitLoad records that a successful Load acknowledged the current library.
	// It stays false while only the lazy path has opened it.
	explicitLoad bool

	// present records which symbols resolved during registerFuncs. It is
	// written under loadMu before ready is set, and only read afterwards.
	present = make(map[string]bool)

	// unbound records symbols the library exports that could not be bound,
	// keyed by symbol name. It follows the same locking discipline as present.
	unbound = make(map[string]error)
)

// SymbolError reports that a symbol is not callable.
//
// Err distinguishes the two ways that happens. A nil Err means the loaded
// library does not export the symbol, which is what an installation older
// than the symbol looks like. A non-nil Err means the library does export
// it and the binding itself failed; the library is not at fault.
type SymbolError struct {
	Symbol string
	Err    error
}

// Error reports the uncallable library symbol and, when the symbol was
// present but could not be bound, why.
func (e *SymbolError) Error() string {
	if e.Err != nil {
		return "cupti: symbol " + e.Symbol + " unavailable: " + e.Err.Error()
	}
	return "cupti: symbol " + e.Symbol + " unavailable"
}

// Unwrap returns the reason the symbol could not be bound, or nil when the
// loaded library does not export it.
func (e *SymbolError) Unwrap() error { return e.Err }

// LibraryConflictError reports a Load call naming a different library than
// the one already loaded. Only one library is loaded per process.
type LibraryConflictError struct {
	Loaded    string
	Requested string

	// Implicit reports that the loaded library was opened lazily and no
	// successful Load has since acknowledged it. A
	// caller that sees this called some
	// other function first, and that call took the default search list.
	Implicit bool
}

// Error reports the conflicting library paths, and whether the library
// that is already loaded got there without a Load call.
func (e *LibraryConflictError) Error() string {
	if e.Implicit {
		return fmt.Sprintf("cupti: an earlier call already loaded %q from the default search list, cannot load %q; call Load before any other function", e.Loaded, e.Requested)
	}
	return fmt.Sprintf("cupti: already loaded from %q, cannot load %q", e.Loaded, e.Requested)
}

// Load opens the shared library from path, or from the default search list
// when path is empty, and binds all symbols. Callers that need to direct
// loading should call Load before any other function; otherwise the first
// call loads from the default search list.
//
// Load is idempotent: calling it again with the same path, or with an empty
// path, returns nil. Calling it with a different path after a successful
// load returns *LibraryConflictError rather than replacing the library.
// After a failed load, Load retries.
func Load(path string) error {
	loadMu.Lock()
	defer loadMu.Unlock()
	if lib != 0 {
		if path != "" && path != libPath {
			return &LibraryConflictError{Loaded: libPath, Requested: path, Implicit: !explicitLoad}
		}
		explicitLoad = true
		return nil
	}
	attempted = false
	explicitLoad = true
	return loadLocked(path)
}

// Loaded reports whether the library is currently loaded. It does not
// trigger a load.
func Loaded() bool {
	return ready.Load()
}

// Path returns the path or name the loaded library was opened from,
// or the empty string if no library is loaded.
func Path() string {
	loadMu.Lock()
	defer loadMu.Unlock()
	return libPath
}

// Has reports whether the named C symbol resolved in the loaded library,
// loading it first if necessary. It returns false if the library failed to
// load. Use it to gate on capabilities before calling into them.
func Has(symbol string) bool {
	if err := checkLib(); err != nil {
		return false
	}
	return present[symbol]
}

// Close unloads the library and clears all bound function pointers.
//
// The function pointers are package-level state, so Close must not be
// called concurrently with any other call into this package: doing so is a
// use-after-free. It is intended for test teardown, not for reclaiming a
// live library.
func Close() error {
	loadMu.Lock()
	defer loadMu.Unlock()
	if lib == 0 {
		return nil
	}
	err := closeLibrary(lib)
	lib = 0
	libErr = nil
	libPath = ""
	attempted = false
	explicitLoad = false
	ready.Store(false)
	present = make(map[string]bool)
	unbound = make(map[string]error)
	clearFuncs()
	if err != nil {
		return fmt.Errorf("cupti: close: %w", err)
	}
	return nil
}

// loadLocked performs the one-time load. It must be called with loadMu held.
func loadLocked(path string) error {
	if attempted {
		return libErr
	}
	attempted = true
	if os.Getenv("CODEGEN_SKIP_BINDINGS") != "" {
		libErr = errors.New("cupti: bindings disabled via CODEGEN_SKIP_BINDINGS")
		return libErr
	}
	lib, libPath, libErr = openLibrary(path)
	if libErr != nil {
		return libErr
	}
	registerFuncs()
	if libErr = checkVersion(); libErr != nil {
		closeLibrary(lib)
		lib = 0
		libPath = ""
		present = make(map[string]bool)
		unbound = make(map[string]error)
		clearFuncs()
		return libErr
	}
	ready.Store(true)
	return nil
}

// VersionMismatchError reports that the shared library that opened is not
// from the version train cupti was generated for. dlsym matches on name
// alone, so a library from a neighbouring train opens and resolves nearly
// every symbol; asking it its own version is what tells the two apart.
type VersionMismatchError struct {
	Path string // the library that was opened
	Want int    // major version these bindings were generated for
	Got  int    // major version the library reports
	Raw  int    // the version value the library reported, undecoded
}

// Error reports which library was opened and the two majors that disagree.
//
// A decoder is only a decoder for the version schemes it was measured
// against, and a library from a train that predates the scheme can report
// a value it does not decode. Naming a major of 0 in that case would
// attribute to the library a claim it never made, so the raw value is
// reported instead.
func (e *VersionMismatchError) Error() string {
	if e.Got == 0 {
		return fmt.Sprintf("cupti: %s reported version %d, which does not decode as a version these bindings recognise; they require major %d", e.Path, e.Raw, e.Want)
	}
	return fmt.Sprintf("cupti: %s reports version major %d, these bindings require %d", e.Path, e.Got, e.Want)
}

// checkVersion asks the loaded library its version through cuptiGetVersion and
// compares the major against 13, the soname major these bindings were
// generated against. It runs under loadMu, after registerFuncs, so it
// calls the bound pointer directly rather than the exported wrapper.
//
// A library that does not export the entry point, or that fails the call,
// is admitted. Absence is what an installation older than the entry point
// looks like, and refusing on it would reject working hosts to catch a
// case the soname already covers.
func checkVersion() error {
	if fnGetVersion == nil {
		return nil
	}
	var out0 uint32
	if err := toError(fnGetVersion(&out0), "cuptiGetVersion"); err != nil {
		return nil
	}
	raw := int(out0)
	if raw > 0 && raw < 1000 {
		return nil
	}
	got := raw / 10000
	if got != 13 {
		return &VersionMismatchError{Path: libPath, Want: 13, Got: got, Raw: raw}
	}
	return nil
}

// openLibrary attempts to load the cupti shared library and reports the
// path it was opened from. An explicit path wins; otherwise it checks the
// library path environment variable, then platform-specific default names.
func openLibrary(path string) (uintptr, string, error) {
	if path == "" {
		path = os.Getenv("CUPTI_LIB_PATH")
	}
	if path != "" {
		h, err := openDynamicLibrary(path)
		if err == nil {
			return h, path, nil
		}
		return 0, "", newLibraryError(path, []LibraryAttempt{{Name: path, Err: err}})
	}
	names := libraryNames()
	var attempts []LibraryAttempt
	for _, name := range names {
		h, err := openDynamicLibrary(name)
		if err == nil {
			return h, name, nil
		}
		attempts = append(attempts, LibraryAttempt{Name: name, Err: err})
	}
	// The bare sonames are all the dynamic linker will find on its own.
	// libcupti is installed outside its default search path, so try the
	// toolkit-relative directories too, but only after the sonames have
	// failed, so nothing changes for a library the linker already resolves.
	for _, name := range toolkitLibraryPaths() {
		h, err := openDynamicLibrary(name)
		if err == nil {
			return h, name, nil
		}
		attempts = append(attempts, LibraryAttempt{Name: name, Err: err})
	}
	return 0, "", newLibraryError("", attempts)
}

// LibraryAttempt records one failed attempt to open the shared library.
type LibraryAttempt struct {
	Name string // path or soname passed to dlopen
	Err  error
}

// LibraryError reports that libcupti could not be opened. Attempts lists
// every name tried in order. Path is set when an explicit path, from Load or
// CUPTI_LIB_PATH, was requested and failed. Hint, when non-empty, says where
// pkg-config believes the library is installed and which toolkit
// directories the dynamic linker does not search.
type LibraryError struct {
	Library  string
	Env      string
	Path     string
	Attempts []LibraryAttempt
	Hint     string
}

// Error describes the library load attempts and their errors.
func (e *LibraryError) Error() string {
	var b strings.Builder
	fmt.Fprintf(&b, "cupti: cannot open %s", e.Library)
	switch {
	case e.Path != "":
		fmt.Fprintf(&b, " at %s", e.Path)
	case len(e.Attempts) == 0:
		fmt.Fprintf(&b, ": no library names for %s/%s", runtime.GOOS, runtime.GOARCH)
	default:
		b.WriteString(": tried ")
		for i, a := range e.Attempts {
			if i > 0 {
				b.WriteString(", ")
			}
			b.WriteString(a.Name)
		}
	}
	if n := len(e.Attempts); n > 0 && e.Attempts[n-1].Err != nil {
		fmt.Fprintf(&b, ": %v", e.Attempts[n-1].Err)
	}
	if e.Hint != "" {
		b.WriteString("; " + e.Hint)
	}
	if e.Path == "" && e.Env != "" {
		fmt.Fprintf(&b, "; set %s to the library path", e.Env)
	}
	return b.String()
}

// Unwrap returns the error from each attempt.
func (e *LibraryError) Unwrap() []error {
	errs := make([]error, 0, len(e.Attempts))
	for _, a := range e.Attempts {
		if a.Err != nil {
			errs = append(errs, a.Err)
		}
	}
	return errs
}

func newLibraryError(path string, attempts []LibraryAttempt) *LibraryError {
	hint := pkgConfigHint()
	if th := toolkitSearchHint(); th != "" {
		if hint != "" {
			hint += "; "
		}
		hint += th
	}
	return &LibraryError{Library: "libcupti", Env: "CUPTI_LIB_PATH", Path: path, Attempts: attempts, Hint: hint}
}

// pkgConfigHint asks pkg-config where the library is installed so that a
// load failure can say so. It runs only after every dlopen attempt has
// failed, never chooses the library, and is silent when pkg-config is
// absent or does not know the package.
func pkgConfigHint() string {
	const pkg = "cupti"
	exe, err := exec.LookPath("pkg-config")
	if err != nil {
		return ""
	}
	out, err := exec.Command(exe, "--variable=libdir", pkg).Output()
	if err != nil {
		return ""
	}
	dir := strings.TrimSpace(string(out))
	if dir == "" {
		return ""
	}
	return "pkg-config reports " + pkg + " in " + dir
}

// toolkitRoots returns the CUDA toolkit roots to search, most specific
// first. CUDA_HOME and CUDA_PATH are the documented overrides;
// /usr/local/cuda is the conventional symlink to the active toolkit.
func toolkitRoots() []string {
	var roots []string
	seen := make(map[string]bool)
	for _, dir := range []string{os.Getenv("CUDA_HOME"), os.Getenv("CUDA_PATH"), "/usr/local/cuda"} {
		if dir == "" || seen[dir] {
			continue
		}
		seen[dir] = true
		roots = append(roots, dir)
	}
	return roots
}

// toolkitLibDirs lists the directories, relative to a toolkit root, that the
// CUDA packages install libcupti into and that the dynamic linker does not
// search.
func toolkitLibDirs() []string {
	return []string{"extras/CUPTI/lib64", "extras/CUPTI/lib", "targets/x86_64-linux/lib"}
}

// toolkitLibraryPaths returns the full paths worth trying once every bare
// soname has failed. Each candidate is stat'ed first, so the loader never
// attempts a file that is not there.
func toolkitLibraryPaths() []string {
	names := libraryNames()
	if len(names) == 0 {
		return nil
	}
	var paths []string
	for _, root := range toolkitRoots() {
		for _, sub := range toolkitLibDirs() {
			for _, name := range names {
				p := filepath.Join(root, sub, name)
				if fi, err := os.Stat(p); err == nil && !fi.IsDir() {
					paths = append(paths, p)
				}
			}
		}
	}
	return paths
}

// toolkitSearchHint names the directories libcupti normally lives in, for a
// load failure message. The dynamic linker does not search them, so a
// correctly installed toolkit still fails to load without one of them on
// the path, and the bare "cannot open" error is otherwise misleading.
func toolkitSearchHint() string {
	var dirs []string
	for _, root := range toolkitRoots() {
		for _, sub := range toolkitLibDirs() {
			dirs = append(dirs, filepath.Join(root, sub))
		}
	}
	if len(dirs) == 0 {
		return ""
	}
	return "libcupti is normally installed in " + strings.Join(dirs, ", ") +
		", which the dynamic linker does not search; add the directory to LD_LIBRARY_PATH"
}

// libraryNames returns the platform-specific shared library names to try.
func libraryNames() []string {
	switch runtime.GOOS {
	case "linux":
		return []string{"libcupti.so.13", "libcupti.so.12", "libcupti.so"}
	default:
		return nil
	}
}

// register uses purego to bind a Go function pointer to a symbol in the cupti
// library, recording whether the symbol resolved. Symbols absent from the
// loaded version are left unbound so the package still works against older
// releases; calling one returns *SymbolError rather than panicking.
func register(fn interface{}, symbol string) {
	if lib == 0 {
		return
	}
	sym, err := lookupLibrarySymbol(lib, symbol)
	if err != nil || sym == 0 {
		return
	}
	if !bindSymbol(fn, sym) {
		unbound[symbol] = errArgumentSlots
		return
	}
	present[symbol] = true
}

// errArgumentSlots is the reason a symbol the library exports could still
// not be bound: the signature needs more argument registers and stack slots
// than this architecture's calling convention provides.
var errArgumentSlots = errors.New("signature needs more argument slots than this architecture provides")

// bindSymbol binds fn to the resolved symbol address sym and reports whether
// the binding succeeded. purego.RegisterFunc panics when it cannot build a
// trampoline for fn's signature; the usual cause is a signature needing more
// argument registers and stack slots than the target architecture allows
// (purego admits 32 arguments on 64-bit platforms, 15 on ppc64le). Recovering
// leaves such a symbol unbound, so calling it reports *SymbolError, rather
// than killing the process at load time.
//
// purego assigns to fn only after every check it can panic on, so a recovered
// binding leaves fn nil.
func bindSymbol(fn interface{}, sym uintptr) (ok bool) {
	defer func() {
		if recover() != nil {
			ok = false
		}
	}()
	purego.RegisterFunc(fn, sym)
	return true
}

// registerSym resolves a symbol to its address and records whether it
// resolved. A symbol absent from the loaded version stays at zero, so
// calling it reports *SymbolError rather than jumping to address zero.
func registerSym(symbol string) uintptr {
	if lib == 0 {
		return 0
	}
	sym, err := lookupLibrarySymbol(lib, symbol)
	if err != nil || sym == 0 {
		return 0
	}
	present[symbol] = true
	return sym
}

